$webp$, chr(10), '') AS header_image
), posts AS (
  INSERT INTO news_posts (category, is_test, header_image)
  SELECT 'update', modes.is_test, artwork.header_image
  FROM (VALUES (false), (true)) AS modes(is_test) CROSS JOIN artwork
  RETURNING id
)
INSERT INTO news_translations (post_id, locale, title, intro, body, header_alt)
SELECT posts.id, copy.locale, copy.title, copy.intro, copy.body, copy.header_alt
FROM posts CROSS JOIN (VALUES
  ('en', 'Meet the daily challenges',
   'There’s a fresh set of puzzles in Aviarium every day. Open Challenges in the menu or from the first Library banner to see what’s on today’s slate, from Sudoku to Nonograms.',
   'Everyone gets the same puzzles, with one attempt per puzzle. Finish before the countdown runs out to put your time on that day’s leaderboard. Solve the whole set and a little parrot will do a victory dance for you.

Missed a day or want another go? Find earlier sets under Leaderboards → Challenges and choose Play this game to replay a puzzle as a regular game.',
   'A green parrot peeks around a calendar with puzzle grids.'),
  ('nl', 'Ontdek de dagelijkse uitdagingen',
   'Elke dag staat er een nieuwe reeks puzzels klaar in Aviarium. Open Uitdagingen via het menu of de eerste banner in de bibliotheek en bekijk wat er vandaag op het programma staat, van sudoku tot nonogrammen.',
   'Iedereen krijgt dezelfde puzzels, met één poging per puzzel. Rond een puzzel af voordat de tijd om is om met je tijd op het dagklassement te komen. Los de hele reeks op en een papegaaitje doet een vreugdedansje voor je.

Een dag gemist of zin om het nog eens te proberen? Eerdere reeksen vind je onder Klassementen → Uitdagingen. Kies Speel dit spel om de puzzel als gewoon spel opnieuw te spelen.',
   'Een groene papegaai gluurt om een kalender met puzzelroosters heen.')
) AS copy(locale, title, intro, body, header_alt);
